constraints:
1 <= T <= 100
1 <= N <= 10^{3}
1 <= A[] <= 10^{3}
1 <= k <= N

expected time complexity: O(Size of tree)
expected auxiliary space: O(1).

standard_solution_code:
class Solution:

	def deleteNode(self, root, k):
		return self.helper(root, k) or root

	def deleteNodeHelper(self, root):
		if root is None:
			return
		if root.left is None and root.right is None:
			del root
			return
		self.deleteNodeHelper(root.left)
		self.deleteNodeHelper(root.right)

	def helper(self, root, k):
		if root is None:
			return None
		if root.data >= k:
			newRoot = root.left
			self.deleteNodeHelper(root.right)
			del root
			return self.helper(newRoot, k)
		else:
			rightChild = self.helper(root.right, k)
			root.right = rightChild
			return root
